Here are some specific codes for using DLL injection in C++:

1. **Using `CreateRemoteThread`:**

```cpp
#include <windows.h>

BOOL InjectDLL(HANDLE hProcess, LPCTSTR szDllPath) {
    HMODULE hModule = GetModuleHandle(NULL);
    LPVOID pRemoteBuf = VirtualAllocEx(hProcess, NULL, strlen(szDllPath) + 1, MEM_COMMIT, PAGE_READWRITE);
    if (pRemoteBuf == NULL) return FALSE;

    WriteProcessMemory(hProcess, pRemoteBuf, (LPVOID)szDllPath, strlen(szDllPath) + 1, NULL);
    HANDLE hThread = CreateRemoteThread(hProcess, NULL, 0, (LPTHREAD_START_ROUTINE)GetProcAddress(hModule, "LoadLibraryA"), pRemoteBuf, 0, NULL);
    if (hThread == NULL) return FALSE;

    WaitForSingleObject(hThread, INFINITE);
    CloseHandle(hThread);
    VirtualFreeEx(hProcess, pRemoteBuf, 0, MEM_RELEASE);
    return TRUE;
}

int main() {
    HANDLE hProcess = OpenProcess(PROCESS_ALL_ACCESS, FALSE, dwProcessId);
    if (hProcess == NULL) return 1;

    BOOL bResult = InjectDLL(hProcess, TEXT("C:\\path\\to\\your\\dll.dll"));
    CloseHandle(hProcess);
    return bResult ? 0 : 1;
}
```

